import { type Tabs as TabsController, type TabsOptions, createTabs } from "@cssints/headless";
import { For, Show, createEffect, createUniqueId } from "solid-js";
import type { JSX } from "@solidjs/web";
import { Accordion } from "./accordion.tsx";

import * as css from "cssints" with { type: "cssints" };

import { t } from "./theme.ts" with { type: "cssints" };

const rootClass = css.display("flex") + " " + css.flexDirection("column");
const listClass = css.cn(
  css.display("flex"),
  // At 320 px and 200 % text four labels do not fit on one line; wrapping is the reflow (G1). The
  // tabs keep their natural width (a flex item's `min-width` is `auto`), so a label is never clipped.
  css.flexWrap("wrap"),
  css.gap(t.space._1),
  css.borderBottom("1px solid", t.color.border),
);
const tabClass = css.cn(
  css.padding(t.space._2, t.space._3),
  // 2.5.8: 24 x 24 CSS px, whatever the label. The padding alone gives 33 px of height and 33 px of
  // width for a one-letter label today, so these only hold the floor if a smaller padding arrives.
  css.minHeight("24px"),
  css.minWidth("24px"),
  // 2.4.12: a browser that reveals the focused tab scrolls it to the top of its scrollport, where a
  // sticky header sits; this keeps it 40 px clear (the registry test puts a 32 px header above it).
  css.scrollMarginTop(t.space._10),
  css.bg("transparent"),
  css.border("none"),
  css.borderBottom("2px solid", "transparent"),
  css.color(t.color.muted),
  css.fontSize(t.font.size),
  css.cursor("pointer"),
  css.hover(css.color(t.color.text)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
  // The underline is heavier when selected, not only a different colour: 3 px against 2 px is the
  // non-colour cue 1.4.1 asks for (G4).
  css.attr("aria-selected", "true")(
    css.color(t.color.text),
    css.borderBottom("3px solid", t.color.highlight),
  ),
  css.attr("aria-disabled", "true")(css.color(t.color.textDisabled), css.cursor("not-allowed")),
);
const panelClass = css.cn(css.padding(t.space._3, 0));

/**
 * APG tabs, styled: a tablist, its tabs and the panels they show.
 *
 * The primitive owns the selection, the roving tab stop and the activation mode (automatic or
 * manual); the host owns the DOM, so this component moves focus to whichever tab the primitive
 * reports as focused — that is what makes a keyboard user's arrow key land somewhere.
 *
 * `value` makes it controlled; without it the tabs own the selection. `onValueChange` is a
 * request — a controlled host may ignore it.
 */
export interface TabsProps extends Omit<TabsOptions, "id"> {
  /** How many tabs; `tab` and `panel` are called per index. */
  readonly items: number;
  readonly tab: (index: number) => JSX.Element;
  readonly panel?: (index: number) => JSX.Element;
  /**
   * The host's narrow breakpoint (TetraLogical: below 800 px). Wide it renders the tablist, narrow it renders
   * the same sections as an accordion, one open, over the same selection. The host measures and passes it —
   * or the fixture listens to `matchMedia("(max-width: 799px)")` — so this stays testable without a resize.
   */
  readonly narrow?: boolean;
  /** The primitive, once: a scenario fixture needs it; a page rarely does. */
  readonly onReady?: (tabs: TabsController) => void;
}

export const Tabs = (props: TabsProps): JSX.Element => {
  const tabs = createTabs({
    items: props.items,
    get value() {
      return props.value;
    },
    defaultSelected: props.defaultSelected,
    orientation: props.orientation,
    activation: props.activation,
    disabled: props.disabled,
    focusablePanels: props.focusablePanels,
    get onValueChange() {
      return props.onValueChange;
    },
  });
  props.onReady?.(tabs);

  let list: HTMLElement | undefined;
  const tabElements = (): HTMLElement[] => [
    ...(list?.querySelectorAll<HTMLElement>('[role="tab"]') ?? []),
  ];
  createEffect(
    () => tabs.focused(),
    (index) => {
      const element = tabElements()[index];
      if (index >= 0 && element !== undefined && document.activeElement !== element) {
        element.focus();
      }
    },
  );

  return (
    <div class={rootClass}>
      {/* Only one mode is in the DOM, so the other is not in the accessibility tree at all: not a hidden
          focusable control, not a second Tab stop for the same section. */}
      <Show when={props.narrow !== true}>
        <div
          {...tabs.tablistProps}
          ref={(element) => {
            list = element;
          }}
          data-part="tablist"
          class={listClass}
        >
          <For each={Array.from({ length: props.items }, (_, index) => index)}>
            {(index) => (
              <button {...tabs.tabProps(index)} data-part="tab" class={tabClass}>
                {props.tab(index)}
              </button>
            )}
          </For>
        </div>
        <For each={Array.from({ length: props.items }, (_, index) => index)}>
          {(index) => (
            <div {...tabs.tabpanelProps(index)} data-part="tabpanel" class={panelClass}>
              {props.panel?.(index)}
            </div>
          )}
        </For>
      </Show>
      {/* The narrow mode is the accordion skin (chevron before the label); its open set is the tabs'
          selection, so shrinking after selecting section 3 opens section 3 and expanding it selects tab 3. */}
      <Show when={props.narrow === true}>
        <Accordion
          items={props.items}
          value={[tabs.selected()]}
          collapsible={false}
          disabledItems={props.disabled}
          trigger={(index) => props.tab(index)}
          panel={(index) => props.panel?.(index)}
          onValueChange={(expanded) => {
            const index = expanded[0];
            if (index !== undefined) {
              tabs.select(index);
            }
          }}
        />
      </Show>
    </div>
  );
};

export interface TabsFallbackProps {
  /** How many sections; `tab` is the heading and the link text, `panel` the content. */
  readonly items: number;
  readonly tab: (index: number) => JSX.Element;
  readonly panel?: (index: number) => JSX.Element;
  /** A section's own id (default `${base}-section-<index>`), shared with the interactive panels. */
  readonly sectionId?: (index: number) => string;
}

/**
 * The no-JS fallback: a list of in-page links, then one heading and the full content per section — the
 * markup a server sends and a reader without script keeps. The host renders it and removes it when the
 * interactive `Tabs` mounts, so the two never meet in the accessibility tree.
 */
export const TabsFallback = (props: TabsFallbackProps): JSX.Element => {
  const base = createUniqueId();
  const idOf = (index: number): string => props.sectionId?.(index) ?? `${base}-section-${index}`;
  const indices = (): number[] => Array.from({ length: props.items }, (_, index) => index);
  return (
    <div data-part="tabs-fallback">
      <ul data-part="fallback-toc">
        <For each={indices()}>
          {(index) => (
            <li>
              <a href={`#${idOf(index)}`}>{props.tab(index)}</a>
            </li>
          )}
        </For>
      </ul>
      <For each={indices()}>
        {(index) => (
          <section id={idOf(index)} data-part="fallback-section">
            <h2>{props.tab(index)}</h2>
            {props.panel?.(index)}
          </section>
        )}
      </For>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { type Tabs as TabsController } from "@cssints/headless";
import type { Json } from "@cssints/apg-specs/scenario";
import type { JSX } from "@solidjs/web";
import type { Mounted } from "./tabs-driver.ts";
import type { TabsConfig } from "@cssints/apg-specs/apg/tabs.bridge";
import { Tabs, TabsFallback } from "./tabs.tsx";
import { createSignal, flush } from "solid-js";
import { render } from "@solidjs/web";

import * as css from "cssints" with { type: "cssints" };

import { t } from "./theme.ts" with { type: "cssints" };

const disabledIndices = (mask: number): ReadonlyArray<number> =>
  [0, 1, 2, 3].filter((index) => ((mask >> index) & 1) === 1);

/**
 * Mounts the styled tabs for the scenario walk. Panel 0 holds the focusable content the ported
 * panel-tabindex scenarios expect. Controlled, the fixture is the host: it keeps the selection in
 * a signal, passes it as `value`, and either writes every request back (`accepts`) or ignores the
 * callback.
 */
export const mountTabs = (config: TabsConfig): Mounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const events = new Map<string, Json[]>();
  const [host, setHost] = createSignal(config.pinned ?? config.selected);
  const writeHost = (next: number): void => {
    if (config.controlled) {
      setHost(next);
    }
  };
  let api: TabsController | undefined;

  const dispose = render(() => {
    return (
      <Tabs
        items={config.items}
        value={config.controlled ? host() : undefined}
        defaultSelected={config.selected}
        orientation={config.orientation}
        activation={config.activation}
        disabled={disabledIndices(config.disabled)}
        focusablePanels={[0]}
        onReady={(controller) => {
          api = controller;
        }}
        onValueChange={(index) => {
          events.set("onSelectionChange", [
            ...(events.get("onSelectionChange") ?? []),
            `tab:${index}`,
          ]);
          if (config.accepts) {
            setHost(index);
          }
        }}
        tab={(index) => `Tab ${index + 1}`}
        panel={(index) => (index === 0 ? <input data-part="input" /> : undefined)}
      />
    );
  }, root);

  return {
    root,
    events,
    setProp: (name, value) => {
      switch (name) {
        case "selectedKey":
        case "selected":
          api?.setSelected(Number(value));
          break;
        case "setValue":
          writeHost(Number(value));
          break;
        default:
          throw new Error(`fixture has no prop ${name}`);
      }
    },
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

export interface SkinMounted {
  readonly root: HTMLElement;
  readonly dispose: () => void;
}

export interface SkinOptions {
  /** The tab labels; the default is `Tab 1` … `Tab 4`. */
  readonly label?: (index: number) => JSX.Element;
}

/**
 * The styled tabs alone: the skin's own requirements (target size, focus, reflow) are about what it
 * renders, not about the primitive's selection, so these mounts skip the scenario driver.
 */
export const mountSkin = (options: SkinOptions = {}): SkinMounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(
    () => (
      <Tabs
        items={4}
        defaultSelected={0}
        tab={(index) => options.label?.(index) ?? `Tab ${index + 1}`}
      />
    ),
    root,
  );
  flush();
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const scrollClass = css.cn(css.height("8rem"), css.overflow("auto"), css.position("relative"));
const headerClass = css.cn(
  css.position("sticky"),
  css.top(0),
  css.zIndex("1"),
  css.height(t.space._8),
  css.bg(t.color.surface),
);
const spacerClass = css.height(t.space._10);
const tallPanelClass = css.height("24rem");

/**
 * A sticky header over a tablist: the composition 2.4.12 is about. The panel is tall so the scroll
 * container can put the tablist at its top, where the header would cover a focused tab without the
 * skin's `scroll-margin-top`.
 */
export const mountTabsUnderStickyHeader = (): SkinMounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(
    () => (
      <div class={scrollClass} data-part="scroll">
        <div class={headerClass} data-part="sticky-header">
          Section
        </div>
        <div class={spacerClass} />
        <Tabs
          items={4}
          defaultSelected={0}
          tab={(index) => `Tab ${index + 1}`}
          panel={() => <div class={tallPanelClass} />}
        />
      </div>
    ),
    root,
  );
  flush();
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const CONTENT_LABEL = (index: number): string => `Section ${index + 1}`;
const CONTENT_PANEL = (index: number): JSX.Element => <p>Content {index + 1}</p>;

/**
 * The skin driven by the catalogue's breakpoint, the way a host drives it: `matchMedia("(max-width: 799px)")`
 * decides `narrow`, so the test only sets the viewport. Wide it is a tablist; narrow the same four sections
 * are the accordion skin, over the same selection.
 */
export const mountBreakpointTabs = (): SkinMounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const query = window.matchMedia("(max-width: 799px)");
  const [narrow, setNarrow] = createSignal(query.matches);
  const onChange = (event: MediaQueryListEvent): void => {
    setNarrow(event.matches);
  };
  query.addEventListener("change", onChange);
  const dispose = render(
    () => (
      <Tabs
        items={4}
        defaultSelected={0}
        narrow={narrow()}
        tab={CONTENT_LABEL}
        panel={CONTENT_PANEL}
      />
    ),
    root,
  );
  flush();
  return {
    root,
    dispose: () => {
      query.removeEventListener("change", onChange);
      dispose();
      root.remove();
    },
  };
};

/** The same four sections as interactive tabs, with their four contents: what must survive the fallback. */
export const mountTabsWithContent = (): SkinMounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(
    () => <Tabs items={4} defaultSelected={0} tab={CONTENT_LABEL} panel={CONTENT_PANEL} />,
    root,
  );
  flush();
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

/** The server's bytes: `TabsFallback` rendered once, then read back as markup, with no script or listeners. */
export const fallbackMarkup = (): string => {
  const holder = document.createElement("div");
  const dispose = render(
    () => (
      <TabsFallback
        items={4}
        tab={CONTENT_LABEL}
        panel={CONTENT_PANEL}
        sectionId={(index) => `tabs-section-${index}`}
      />
    ),
    holder,
  );
  const html = holder.innerHTML;
  dispose();
  return html;
};

/** A static document: the fallback's markup alone, injected, never hydrated. */
export const mountStaticFallback = (): SkinMounted => {
  const root = document.createElement("div");
  root.innerHTML = fallbackMarkup();
  document.body.append(root);
  return {
    root,
    dispose: () => root.remove(),
  };
};

import { type ActionStep, type Driver, type Json, Unsupported } from "@cssints/apg-specs/scenario";
import { flush } from "solid-js";
import { userEvent } from "vite-plus/test/browser";

/**
 * The generic DOM side of the scenario bridge. A pattern's fixture renders its
 * parts with `data-part="<name>"` and returns a `Mounted`; this turns scenario
 * steps into real pointer/keyboard input and DOM reads into observations.
 */
export interface Mounted {
  readonly root: HTMLElement;
  /** Apply a scenario `prop` step (programmatic input) to the mounted widget. */
  readonly setProp: (name: string, value: Json | undefined) => void;
  /** Callback payloads, recorded under their canonical name. */
  readonly events: ReadonlyMap<string, ReadonlyArray<Json>>;
  readonly value?: () => Json;
  /**
   * The part the primitive itself considers focused (`trigger`, `tab:1`), or
   * `null`. Preferred over `document.activeElement` so the walk does not race the
   * fixtures' deferred DOM focus (bean 209r).
   */
  readonly focus?: () => string | null;
  readonly dispose: () => void;
}

export interface DomDriverOptions {
  /** Parts that can be hidden: the ones `expect.visible` lists. */
  readonly hideableParts: ReadonlyArray<string>;
  readonly eventName?: (name: string) => string;
}

const BOOLEAN_ATTRS = new Set(["hidden", "disabled"]);
const REFERENCE_ATTRS = new Set([
  "aria-controls",
  "aria-labelledby",
  "aria-owns",
  "aria-activedescendant",
]);
const NAMED_KEYS = new Set(["Enter", "Tab", "Escape", "Backspace", "Delete", "Home", "End"]);

// Solid renders on its own schedule, but `flush()` applies the queued signal work
// synchronously; the fixtures then move DOM focus in a `setTimeout(0)` macrotask
// (kept for user-event's Enter semantics). Waiting one macrotask lets both land
// before the walk reads, without a frame — a frame also lets the browser's focus
// fixup run and perturb the observation (bean 209r). The walk reads focus from
// the fixture's primitive state when it offers one (`Mounted.focus`).
const settle = (): Promise<void> => {
  flush();
  return new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
};

const keyboardSyntax = (key: string): string => {
  if (key === "Space" || key === " ") {
    return " ";
  }
  return NAMED_KEYS.has(key) || key.startsWith("Arrow") || key.startsWith("Page")
    ? `{${key}}`
    : key;
};

// A held key is always written by name: `{Space>}` keeps it down, `{/Space}`
// releases it wherever focus is at that moment (a blur between the two halves
// is exactly what a walk needs to see).
const keyName = (key: string) => (key === " " || key === "Space" ? "Space" : key);

/** `KeyboardEvent.key` uses a space character, not the `Space` alias. */
const eventKey = (key: string) => (key === "Space" ? " " : key);

const CLICKABLE_INPUT_TYPES = new Set([
  "button",
  "color",
  "file",
  "image",
  "reset",
  "submit",
  "checkbox",
  "radio",
]);

/**
 * A half press is dispatched directly (not through user-event's held-key state,
 * which auto-releases on a repeated down and leaks across walk drivers). The
 * two native activations user-event would otherwise add are emulated: Space
 * clicks a button-like element on keyup, Enter on keydown.
 */
const halfPress = (target: EventTarget | null, type: "keydown" | "keyup", key: string) => {
  if (!(target instanceof HTMLElement)) {
    return;
  }
  const keyValue = eventKey(key);
  const notPrevented = target.dispatchEvent(
    new KeyboardEvent(type, {
      key: keyValue,
      code: keyName(key),
      bubbles: true,
      cancelable: true,
    }),
  );
  const clickable =
    target.tagName === "BUTTON" ||
    (target instanceof HTMLInputElement && CLICKABLE_INPUT_TYPES.has(target.type));
  if (
    notPrevented &&
    clickable &&
    ((type === "keyup" && keyValue === " ") || (type === "keydown" && keyValue === "Enter"))
  ) {
    target.click();
  }
};

export const domDriver = (mounted: Mounted, options: DomDriverOptions): Driver => {
  const { root } = mounted;
  const canonical = options.eventName ?? ((name: string) => name);

  const partsOf = (name: string): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>(`[data-part="${name}"]`),
  ];

  const targetOf = (element: HTMLElement): string => {
    const name = element.dataset["part"] ?? "";
    return `${name}:${partsOf(name).indexOf(element)}`;
  };

  const elementOf = (target: string): HTMLElement => {
    const [name = "", index = "0"] = target.split(":");
    const element = partsOf(name)[Number(index)];
    if (element === undefined) {
      throw new Unsupported(`part ${target}`);
    }
    return element;
  };

  const click = async (element: HTMLElement): Promise<void> => {
    // a disabled button is not actionable; force lets the browser drop the click itself
    await userEvent.click(element, { force: true });
  };

  // Half presses this driver dispatched a keydown for, so a stray `phase: "up"`
  // stays inert (the spec's key_up only fires on an armed press).
  const halfHeld = new Set<string>();

  return {
    perform: async (step: ActionStep) => {
      switch (step.event) {
        case "focus":
          elementOf(step.target ?? "").focus();
          break;
        case "blur":
          halfHeld.clear();
          elementOf(step.target ?? "").blur();
          break;
        case "click":
          await click(elementOf(step.target ?? ""));
          break;
        case "pointerdown":
          elementOf(step.target ?? "").focus();
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointerdown", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "pointerup": {
          const element = elementOf(step.target ?? "");
          element.dispatchEvent(
            new PointerEvent("pointerup", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          // a released pointer button is a click, as the browser would deliver it
          element.click();
          break;
        }
        case "pointercancel":
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointercancel", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "hover":
          await userEvent.hover(elementOf(step.target ?? ""));
          break;
        case "unhover":
          await userEvent.unhover(elementOf(step.target ?? ""));
          break;
        case "key": {
          if (step.phase === "down") {
            const element = elementOf(step.target ?? "");
            if (document.activeElement !== element) {
              element.focus();
            }
            // a disabled/read-only control never arms (the spec's spaceArms
            // guard), so a later `up` must not activate it either
            const blocked =
              element.getAttribute("aria-disabled") === "true" ||
              element.getAttribute("aria-readonly") === "true" ||
              (element instanceof HTMLButtonElement && element.disabled);
            if (!blocked) {
              halfHeld.add(keyName(step.key ?? ""));
            }
            halfPress(element, "keydown", step.key ?? "");
            break;
          }
          if (step.phase === "up") {
            if (!halfHeld.delete(keyName(step.key ?? ""))) {
              break;
            }
            // release wherever focus went: deliberately do NOT re-focus the
            // target, or a keydown -> blur -> keyup walk would be defeated
            const active = document.activeElement;
            halfPress(
              active instanceof HTMLElement ? active : document.body,
              "keyup",
              step.key ?? "",
            );
            break;
          }
          const element = elementOf(step.target ?? "");
          if (document.activeElement !== element) {
            element.focus();
          }
          // a whole press releases the key, so a later `phase: "up"` is inert
          halfHeld.delete(keyName(step.key ?? ""));
          await userEvent.keyboard(keyboardSyntax(step.key ?? ""));
          break;
        }
        case "prop":
          if (step.set !== undefined) {
            for (const [name, value] of Object.entries(step.set)) {
              mounted.setProp(name, value);
              if ((name === "disabled" || name === "isDisabled") && value === true) {
                // the spec drops a pending press when the control disables
                halfHeld.clear();
              }
            }
          } else {
            mounted.setProp(step.prop ?? "", step.value);
            if ((step.prop === "disabled" || step.prop === "isDisabled") && step.value === true) {
              halfHeld.clear();
            }
          }
          break;
        default:
          throw new Unsupported(`event ${step.event}`);
      }
      await settle();
    },
    observer: {
      focus: () => {
        // Prefer the primitive's own focus: the fixtures sync DOM focus in a
        // deferred macrotask (kept for user-event's Enter semantics), so reading
        // `document.activeElement` here races that (bean 209r).
        if (mounted.focus !== undefined) {
          return mounted.focus();
        }
        const active = document.activeElement;
        const part =
          active instanceof HTMLElement ? active.closest<HTMLElement>("[data-part]") : null;
        return part !== null && root.contains(part) ? targetOf(part) : null;
      },
      attr: (target, name) => {
        if (name.startsWith("data-")) {
          throw new Unsupported(`styling hook ${name}`);
        }
        const value = elementOf(target).getAttribute(name);
        if (value === null) {
          return null;
        }
        if (value === "" && BOOLEAN_ATTRS.has(name)) {
          return "true";
        }
        if (REFERENCE_ATTRS.has(name)) {
          const referenced = root.querySelector<HTMLElement>(`[id="${value}"]`);
          return referenced?.dataset["part"] === undefined ? value : targetOf(referenced);
        }
        return value;
      },
      visible: () =>
        options.hideableParts.flatMap((name) =>
          partsOf(name)
            .filter((element) => element.checkVisibility())
            .map(targetOf),
        ),
      events: (name) => mounted.events.get(canonical(name)) ?? [],
      ...(mounted.value === undefined ? {} : { value: mounted.value }),
    },
    dispose: mounted.dispose,
  };
};

